"""Headline attack and cost numbers, regenerated by one command (M8).

Requirement 8.3-8.7 and the evaluation plan (R12). `repro.sh` calls this module;
it writes `backend/results/repro.json`, which is committed, and it must finish in
under 600 seconds.

What is deterministic and what is not
-------------------------------------
Outcomes and sizes are deterministic: KGA success, replay/plant outcomes, the
on-chain leak check, storage overhead, and the parameters of every lattice
value. Two runs with the same seed produce identical values for those, and
`deterministic_headline()` is the exact subset the determinism test compares
(Requirement 8.7).

Wall-clock timings are measured, not deterministic, by definition. They are
reported in the same file but under keys that say so (`*_ms`), and no timing ever
feeds a security claim. Mixing the two would make "reproducible" mean nothing.

Archived sweeps stay out of this path (Requirement 8.5): `sweep.py`, `boundary*`,
`nq_*`, `end_to_end`, `forward_sec` and `recovery` are still runnable, but this
module must not import them.
"""

from __future__ import annotations

import argparse
import json
import time
from pathlib import Path

import numpy as np

from .config import MedVaultConfig, library_versions
from .consent import ConsentError
from .envelope import Scope
from .harness import KEYWORD_DICTIONARY, run_all_attacks
from .kem import size_report
from .pir import measure_pir
from .service import build_world
from .zk import ZKAuthorisation

RESULTS_DIR = Path(__file__).resolve().parent.parent / "results"
DEFAULT_OUTPUT = RESULTS_DIR / "repro.json"

#: Explicitly excluded from this path. Each is still runnable on its own.
ARCHIVED_SWEEPS = (
    "sweep", "boundary", "nq_sweep", "end_to_end", "forward_sec", "recovery",
)

#: The (records, doctors) grid for the latency table. Small on purpose: this is
#: a demo laptop, and the claim is "measured", not "large".
LATENCY_GRID = ((25, 1), (25, 3), (100, 3))

#: Index mode A costs one PEKS operation per indexed entry, so it is measured
#: once at the smallest size rather than across the whole grid.
MODE_A_LATENCY_GRID = ((10, 1),)

#: PIR database sizes measured for the size/latency table (Requirement 12.7).
PIR_GRID = (16, 256, 1024)


def _timed(fn, *args, **kwargs):
    started = time.perf_counter()
    value = fn(*args, **kwargs)
    return value, (time.perf_counter() - started) * 1000.0


# --------------------------------------------------------------------------
# Latency
# --------------------------------------------------------------------------

def measure_search_latency(config: MedVaultConfig, *, mode: str = "B",
                           grid=LATENCY_GRID, queries: int = 10) -> list[dict]:
    """Wall-clock search latency across record and doctor counts.

    Three columns, because the interesting claim is a comparison: a plaintext
    index (the "no crypto at all" floor), the keyed index (this system), and the
    PPSEB toy index (mode A) at a size it can actually finish.
    """
    rows: list[dict] = []
    for records, doctors in grid:
        world = build_world(config, mode=mode)
        keywords = KEYWORD_DICTIONARY
        record_ids = [f"rec-{i:03d}" for i in range(records)]
        for i, record_id in enumerate(record_ids):
            keyword = keywords[i % len(keywords)]
            world.upload_record(record_id, f"record {i}", [keyword, "shared"])

        scope = Scope.record_set(record_ids)
        for index in range(doctors):
            world.grant_scope(f"doctor_{chr(ord('a') + index)}", scope)

        doctor_id = "doctor_a"
        # Plaintext baseline: a dict of keyword -> record ids, scanned directly.
        plaintext = {}
        for i, record_id in enumerate(record_ids):
            plaintext.setdefault(keywords[i % len(keywords)], []).append(record_id)
        _plaintext_results, plaintext_ms = _timed(
            lambda: [plaintext.get(keywords[j % len(keywords)], [])
                     for j in range(queries)]
        )
        _searches, search_ms = _timed(
            lambda: [world.search(doctor_id, keywords[j % len(keywords)])
                     for j in range(queries)]
        )

        rows.append({
            "records": records,
            "doctors": doctors,
            "mode": mode,
            "queries": queries,
            "plaintext_index_ms_per_query": round(plaintext_ms / queries, 4),
            "keyed_index_ms_per_query": round(search_ms / queries, 4),
            "keyed_index_total_ms": round(search_ms, 3),
            "index_entries": world.node.total_entries(),
        })
    return rows


def measure_mode_a_latency(config: MedVaultConfig, *, queries: int = 5) -> list[dict]:
    """The PPSEB toy index, measured once: `verify` runs per entry per search."""
    rows = []
    for records, doctors in MODE_A_LATENCY_GRID:
        world = build_world(config, mode="A")
        record_ids = [f"rec-{i:03d}" for i in range(records)]
        for i, record_id in enumerate(record_ids):
            world.upload_record(record_id, f"record {i}",
                                [KEYWORD_DICTIONARY[i % len(KEYWORD_DICTIONARY)]])
        world.grant_scope("doctor_a", Scope.record_set(record_ids))
        _results, elapsed_ms = _timed(
            lambda: [world.search("doctor_a", KEYWORD_DICTIONARY[j % len(KEYWORD_DICTIONARY)])
                     for j in range(queries)]
        )
        rows.append({
            "records": records,
            "doctors": doctors,
            "mode": "A",
            "queries": queries,
            "ppseb_toy_ms_per_query": round(elapsed_ms / queries, 3),
            "index_entries": world.node.total_entries(),
            "params": {"n": world.params.n, "q": world.params.q,
                       "sigma": world.params.sigma, "l": world.params.l},
        })
    return rows


# --------------------------------------------------------------------------
# Privacy layer and research arm (phase 2 and 3)
# --------------------------------------------------------------------------

def measure_pir_table(config: MedVaultConfig, *, fast: bool = False) -> list[dict]:
    """PIR hint, query and answer sizes against database size (R5.3, R12.7)."""
    return measure_pir(PIR_GRID[:2] if fast else PIR_GRID, seed=config.seed)


def measure_zk(config: MedVaultConfig, *, fast: bool = False) -> dict:
    """Groth16 proving and verification cost, or why it was not measured.

    Skipped when the circuit has not been built: a fabricated timing would be
    worse than an explicit absence.
    """
    if not ZKAuthorisation.available():
        return {"available": False,
                "reason": "circuits not built: run `npm --prefix circuits run build`"}
    import json
    from .zk import CIRCUITS

    setup = json.loads((CIRCUITS / "build" / "setup_meta.json").read_text())
    world = build_world(MedVaultConfig(seed=config.seed,
                                       slot_size=config.slot_size, zk_mode="groth16"))
    world.upload_record("rec-zk", "hba1c 7.4", ["diabetes"], tag="lab")
    world.grant_scope("doctor_a", Scope.record_tag("lab"))
    _result, prove_ms = _timed(world.search, "doctor_a", "diabetes")
    proof = world.doctors["doctor_a"].last_request.zk_proof
    verify = world.zk.verify_proof(proof["proof"], proof["public_inputs"])
    return {
        "available": True,
        "system": "Groth16 over BN254 (classical)",
        "trusted_setup": setup["trusted_setup"],
        "constraints": setup["constraints"],
        "depth": setup["depth"],
        "zkey_bytes": setup["zkey_bytes"],
        "proof_bytes": len(json.dumps(proof["proof"])),
        "public_inputs": setup["public_inputs"],
        "prove_and_search_ms": round(prove_ms, 1),
        "verify_ms": round(world.zk.last_verification_ms, 2),
        "verified": verify,
        "nullifiers_consumed": world.ledger.nullifier_count(),
    }


def measure_tree_norms(config: MedVaultConfig, *, fast: bool = False) -> dict:
    """M7: Gram-Schmidt norm per level and the PEKS match matrix."""
    from .key_tree import KeyTree, KeyTreeConfig

    tree = KeyTree(KeyTreeConfig(depth=3 if fast else 4, seed=config.seed)).build()
    rows = tree.norm_summary()
    peks = [] if fast else tree.measure_peks()
    return {
        "depth": tree.config.depth,
        "nodes": len(tree.nodes),
        "params": {"n": tree.config.params.n, "q": tree.config.params.q,
                   "sigma": tree.config.params.sigma, "l": tree.config.params.l},
        "all_nodes_correct": all(tree.check_all_correctness().values()),
        "norms_per_level": rows,
        "max_norm_within_threshold": all(r["usable"] for r in rows),
        "peks_same_epoch_matches": sum(r["same_epoch_match"] for r in peks),
        "peks_cross_epoch_matches": sum(r["cross_epoch_match"] for r in peks),
        "peks_epochs": len(peks),
        "claim": "structure implemented and measured; no forward-security claim",
    }


def measure_gas(config: MedVaultConfig) -> dict:
    """Gas per consent event on the local Hardhat chain, or why it is absent."""
    try:
        world = build_world(MedVaultConfig(seed=config.seed, zk_mode="groth16"
                                           if ZKAuthorisation.available() else "signed",
                                           ledger_mode="hardhat"))
    except ConsentError as exc:
        return {"available": False, "reason": f"{exc.reason}: {exc.detail}"}

    world.upload_record("rec-gas", "body", ["diabetes"], tag="lab")
    world.grant_scope("doctor_a", Scope.record_tag("lab"))
    world.search("doctor_a", "diabetes")
    world.revoke_doctor("doctor_a")

    by_operation: dict[str, list[int]] = {}
    for receipt in world.ledger.gas_receipts:
        by_operation.setdefault(receipt["operation"], []).append(receipt["gas"])
    return {
        "available": True,
        "backend": world.ledger.backend_label,
        "chain_id": 31337,
        "proof_enforced_on_chain": world.ledger.require_proof,
        "gas": {op: {"calls": len(values), "mean": int(sum(values) / len(values)),
                     "max": max(values)}
                for op, values in by_operation.items()},
        "event_names": sorted({e["type"] for e in world.ledger.chain_log()}),
    }


# --------------------------------------------------------------------------
# Storage and revocation
# --------------------------------------------------------------------------

def measure_storage_overhead(config: MedVaultConfig) -> dict:
    """Bytes per record, per envelope, and per index entry (Requirement 12.5)."""
    world = build_world(config, mode="B")
    payload = "x" * 256
    upload, _ = world.upload_record("rec-001", payload, ["diabetes", "shared"], tag="lab")
    grant, _ = world.grant_scope("doctor_a", Scope.record_set(["rec-001"]))
    entry = world.node.entries("doctor_a", 0)[0]

    plaintext_bytes = len(payload)
    return {
        "record_plaintext_bytes": plaintext_bytes,
        "record_ciphertext_bytes": upload["ciphertext_bytes"],
        "record_overhead_bytes": upload["ciphertext_bytes"] - plaintext_bytes,
        "envelope_bytes": grant["envelope"]["total_bytes"],
        "envelope_kem_ciphertext_bytes": grant["envelope"]["kem_ciphertext_bytes"],
        "envelope_sealed_payload_bytes": grant["envelope"]["sealed_payload_bytes"],
        "index_entry_bytes": len(entry.token) + len(entry.patient_signature),
        "index_entry_token_bytes": len(entry.token),
        "index_entry_signature_bytes": len(entry.patient_signature),
        "note": ("index entry = 32-byte HMAC token + 64-byte Ed25519 signature; "
                 "the PEKS entry in mode A stores a full ciphertext instead"),
        "kem": size_report(world.kem),
    }


def measure_revocation_cost(config: MedVaultConfig, *, records: int = 20,
                            doctors: int = 3) -> dict:
    """Time and operation counts for one revocation (Requirement 12.4)."""
    world = build_world(config, mode="B")
    record_ids = [f"rec-{i:03d}" for i in range(records)]
    for i, record_id in enumerate(record_ids):
        world.upload_record(record_id, f"record {i}",
                            [KEYWORD_DICTIONARY[i % len(KEYWORD_DICTIONARY)], "shared"])
    scope = Scope.record_set(record_ids)
    for index in range(doctors):
        world.grant_scope(f"doctor_{chr(ord('a') + index)}", scope)

    result, _ = world.revoke_doctor("doctor_a")
    cost = dict(result["cost"])
    cost["records_in_scope"] = records
    cost["doctors_before"] = doctors
    cost["doctors_after"] = len(result["remaining_doctors"])
    return cost


def measure_shape_check(config: MedVaultConfig, *, samples: int) -> dict:
    """False-reject rate of the mode A′ shape check on honest PEKS ciphertexts."""
    from ppseb.params import default_params
    from ppseb.scheme import initialization

    from .wellformed import measure_false_rejects

    params = default_params()
    state = initialization(params, np.random.default_rng(config.sub_seed("shape-check-keys")))
    return measure_false_rejects(params, state["pk_r0"], state["mu"], samples=samples,
                                 seed=config.sub_seed("shape-check-honest"))


# --------------------------------------------------------------------------
# Assembly
# --------------------------------------------------------------------------

def run_repro(seed: int = 42, *, fast: bool = False) -> dict:
    """Regenerate every headline number. Must stay under 600 seconds."""
    config = MedVaultConfig(seed=seed)
    started = time.perf_counter()

    attacks = run_all_attacks(config, kga_rates=True, kga_seeds=1 if fast else 2)
    kga_success = {
        f"mode_{mode}": {attacker: attacks["kga"][f"mode_{mode}"][attacker]["success_rate_pct"]
                         for attacker in attacks["kga"][f"mode_{mode}"]}
        for mode in ("A", "B")
    }
    kga_trials = {
        f"mode_{mode}": {attacker: {k: cell[k] for k in (
                             "successes", "trials", "wrong_keyword_matches",
                             "own_ciphertext_failures", "success_rate_given_working_search_pct")}
                         for attacker, cell in attacks["kga"][f"mode_{mode}"].items()}
        for mode in ("A", "B")
    }
    kga_trials["control_unkeyed_hash"] = {
        k: attacks["kga"]["control_unkeyed_hash"][k]
        for k in ("successes", "trials", "success_rate_pct")}
    replay_plant = {
        f"mode_{mode}": {
            "replay": attacks["replay"][mode]["replay_ok"],
            "plant": attacks["plant"][mode]["appears_in_search"],
            "replay_reason": attacks["replay"][mode]["replay_reason"],
            "plant_reason": attacks["plant"][mode]["reason"],
        }
        for mode in ("A", "B")
    }

    plant_checked = attacks["plant"]["A′"]
    shape_check = {
        "plant_mode_A_prime": {"plant": plant_checked["appears_in_search"],
                               "plant_reason": plant_checked["reason"],
                               "honest_entries_indexed": plant_checked["honest_entries_indexed"]},
        "honest_false_rejects": measure_shape_check(config, samples=200 if fast else 1000),
    }
    retrieval_replay = {
        f"mode_{mode}": {"replay": attacks["retrieval_replay"][mode]["replay_ok"],
                         "replay_reason": attacks["retrieval_replay"][mode]["replay_reason"]}
        for mode in ("A", "B")
    }

    storage = measure_storage_overhead(config)
    revocation = measure_revocation_cost(config, records=10 if fast else 20)
    latency = measure_search_latency(config, grid=((10, 1),) if fast else LATENCY_GRID)
    if not fast:
        latency += [dict(row, mode="A") for row in measure_mode_a_latency(config)]
    pir = measure_pir_table(config, fast=fast)
    zk = measure_zk(config, fast=fast)
    tree = measure_tree_norms(config, fast=fast)
    gas = measure_gas(config)

    world = build_world(config, mode="B")
    elapsed = time.perf_counter() - started

    return {
        "meta": {
            "generated_by": "medvault.repro",
            "seed": seed,
            "library_versions": library_versions(),
            "kem_label": world.kem.label(),
            "ledger_backend": world.ledger.backend_label,
            "lattice_params": {"n": world.params.n, "q": world.params.q,
                               "sigma": world.params.sigma, "l": world.params.l},
            "archived_sweeps_excluded": list(ARCHIVED_SWEEPS),
            "elapsed_s": round(elapsed, 2),
        },
        "kga_success": kga_success,
        "kga_trials": kga_trials,
        "replay_plant": replay_plant,
        "retrieval_replay": retrieval_replay,
        "shape_check": shape_check,
        "access_pattern": {
            f"mode_{mode}": {
                "token_on_chain": attacks["access_pattern"][mode]["token_on_chain"],
                "log_entries": attacks["access_pattern"][mode]["log_entries"],
            }
            for mode in ("A", "B")
        },
        "search_latency_ms": latency,
        "storage_overhead": storage,
        "revocation_cost": revocation,
        "pir": pir,
        "zk": zk,
        "tree_evolution_norm": tree,
        "gas_per_consent_event": gas,
        "not_yet_measured": {k: v for k, v in {
            "pir": None if pir else "M5 (phase 2)",
            "zk": None if zk.get("available") else zk.get("reason"),
            "tree_evolution_norm": None if tree else "M7 (phase 3)",
            "gas_per_consent_event": None if gas.get("available") else gas.get("reason"),
        }.items() if v},
        "claims": {
            "can_say": [
                "each finding has a named fix and a regression test",
                "cost and leakage are measured",
                "key wrapping and PIR use lattice assumptions",
            ],
            "do_not_say": [
                "post-quantum system",
                "PPSEB is Module-LWE",
                "forward security proven",
                "revocation recalls downloaded data",
                "LWE is broken",
                "production-ready",
            ],
        },
    }


def deterministic_headline(result: dict) -> dict:
    """The subset that must be byte-identical between two runs (Requirement 8.7).

    Outcomes, sizes and parameters. Not timings — those are measurements of the
    machine, and pretending otherwise would make the determinism claim false.
    """
    return {
        "kga_success": result["kga_success"],
        "kga_trials": result["kga_trials"],
        "replay_plant": result["replay_plant"],
        "retrieval_replay": result["retrieval_replay"],
        "shape_check": result["shape_check"],
        "access_pattern": result["access_pattern"],
        "storage_overhead": result["storage_overhead"],
        "lattice_params": result["meta"]["lattice_params"],
        "kem_label": result["meta"]["kem_label"],
        "zk_constraints": (result["zk"] or {}).get("constraints"),
        "tree_all_nodes_correct": (result["tree_evolution_norm"] or {}).get("all_nodes_correct"),
        "pir_query_bytes": [row["query_bytes"] for row in result["pir"]],
    }


def write_results(result: dict, output: Path = DEFAULT_OUTPUT) -> Path:
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(result, indent=2), encoding="utf-8")
    return output


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Regenerate MedVault-PQ headline numbers")
    parser.add_argument("--seed", type=int, default=42)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    parser.add_argument("--fast", action="store_true",
                        help="smaller grids, for a quick check")
    args = parser.parse_args(argv)

    result = run_repro(args.seed, fast=args.fast)
    path = write_results(result, args.output)

    summary = result["kga_success"]
    print(f"wrote {path}")
    print(f"  seed={args.seed} kem={result['meta']['kem_label']} "
          f"({result['meta']['elapsed_s']}s)")
    print(f"  KGA outsider  mode A {summary['mode_A']['outsider']}%  "
          f"mode B {summary['mode_B']['outsider']}%")
    print(f"  KGA insider   mode A {summary['mode_A']['insider']}%  "
          f"mode B {summary['mode_B']['insider']}%")
    print(f"  replay        mode A {result['replay_plant']['mode_A']['replay']}  "
          f"mode B {result['replay_plant']['mode_B']['replay']}")
    print(f"  plant         mode A {result['replay_plant']['mode_A']['plant']}  "
          f"mode A′ {result['shape_check']['plant_mode_A_prime']['plant']}  "
          f"mode B {result['replay_plant']['mode_B']['plant']}")
    fr = result["shape_check"]["honest_false_rejects"]
    print(f"  shape check   {fr['false_rejects']}/{fr['samples']} honest ciphertexts refused")
    print(f"  fetch replay  mode A {result['retrieval_replay']['mode_A']['replay']}  "
          f"mode B {result['retrieval_replay']['mode_B']['replay']}")
    zk, tree, gas = result["zk"], result["tree_evolution_norm"], result["gas_per_consent_event"]
    print(f"  zk            {zk.get('constraints')} constraints, verified={zk.get('verified')}")
    print(f"  key tree      nodes correct={tree['all_nodes_correct']}, "
          f"norms within threshold={tree['max_norm_within_threshold']}")
    print(f"  gas           {'measured' if gas.get('available') else gas.get('reason')}")
    return 0


if __name__ == "__main__":  # pragma: no cover - CLI entry point
    raise SystemExit(main())
